import React, { useState, useMemo } from 'react';
import { Studente, Lezione, Uda, TimetableSettings, AiSettings, Valutazione, ValutazioneCompetenza, DocumentTemplate } from '../types';
import { generateStudentProfilePdf, generateLessonPdf, generateHtmlDocxBlob } from '../utils/documentUtils';
import { saveAs } from '../utils/documentUtils';
import { useSystemStore } from '../stores/useSystemStore';
import { useUIStore } from '../stores/useUIStore';
import TemplateManager from './TemplateManager';
import JSZip from 'jszip';
import { M3Dialog, M3DialogContent, M3DialogActions, M3Button } from './ui';
import { useTheme } from '../theme/theme';

// Type guards migliorati
const isStudent = (data: unknown): data is Studente => {
  return (
    data !== null &&
    typeof data === 'object' &&
    'nome' in data &&
    'cognome' in data &&
    typeof (data as Record<string, unknown>).nome === 'string' &&
    typeof (data as Record<string, unknown>).cognome === 'string'
  );
};

const isLesson = (data: unknown): data is Lezione => {
  return (
    data !== null &&
    typeof data === 'object' &&
    'contenuto' in data &&
    'materia' in data &&
    typeof (data as Record<string, unknown>).contenuto === 'string' &&
    typeof (data as Record<string, unknown>).materia === 'string'
  );
};

const isUda = (data: unknown): data is Uda => {
  return (
    data !== null &&
    typeof data === 'object' &&
    'title' in data &&
    'classe' in data &&
    typeof (data as Record<string, unknown>).title === 'string' &&
    typeof (data as Record<string, unknown>).classe === 'string'
  );
};

// Tipi per l'export multiplo
export interface BatchDocument {
  id: string;
  type: 'student_profile' | 'lesson_plan' | 'uda' | 'syllabus' | 'council_report';
  title: string;
  subtitle: string;
  data: Studente | Lezione | Uda | { class: string; subject: string; lessons: Lezione[] }; // Tipi specifici invece di any
  format: 'pdf' | 'docx';
  selected: boolean;
}

interface BatchExportWizardProps {
  onClose: () => void;
  students: Studente[];
  lessons: Record<string, Lezione>;
  uda: Uda[];
  evaluations: Valutazione[];
  competencyEvaluations: ValutazioneCompetenza[];
  settings: TimetableSettings;
  aiSettings: AiSettings;
  userClasses: string[];
}

const BatchExportWizard: React.FC<BatchExportWizardProps> = (props) => {
  const { layers } = useTheme();
  const [selectedDocuments, setSelectedDocuments] = useState<BatchDocument[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState<{ current: number; total: number; currentDoc: string } | null>(null);
  const [showTemplateManager, setShowTemplateManager] = useState(false);

  const { showToast } = useUIStore(state => ({ showToast: state.actions.showToast }));
  const { trackAnalyticsEvent } = useSystemStore(state => ({ trackAnalyticsEvent: state.actions.trackAnalyticsEvent }));

  // Track apertura wizard
  React.useEffect(() => {
    trackAnalyticsEvent('feature_usage', 'batch_export_wizard');
  }, [trackAnalyticsEvent]);

  // Genera la lista di tutti i documenti disponibili
  const availableDocuments = useMemo((): BatchDocument[] => {
    const docs: BatchDocument[] = [];

    // Profili Studente
    props.students.forEach(student => {
      docs.push({
        id: `student-${student.id}`,
        type: 'student_profile',
        title: `Profilo ${student.cognome} ${student.nome}`,
        subtitle: `Classe ${student.classe}`,
        data: student,
        format: 'pdf',
        selected: false
      });
    });

    // Piani Lezione
    Object.values(props.lessons).forEach(lesson => {
      docs.push({
        id: `lesson-${lesson.id}`,
        type: 'lesson_plan',
        title: `Piano: ${lesson.contenuto}`,
        subtitle: `${lesson.materia} - ${lesson.classe}`,
        data: lesson,
        format: 'pdf',
        selected: false
      });
    });

    // UDA
    props.uda.forEach(uda => {
      docs.push({
        id: `uda-${uda.id}`,
        type: 'uda',
        title: `UDA: ${uda.title}`,
        subtitle: `Classe ${uda.classe}`,
        data: uda,
        format: 'docx', // Corretto: UDA genera DOCX
        selected: false
      });
    });

    return docs;
  }, [props.students, props.lessons, props.uda]);

  const toggleDocumentSelection = (docId: string) => {
    setSelectedDocuments(prev =>
      prev.some(d => d.id === docId)
        ? prev.filter(d => d.id !== docId)
        : [...prev, availableDocuments.find(d => d.id === docId)!]
    );
  };

  const selectAll = () => {
    setSelectedDocuments(availableDocuments);
  };

  const selectNone = () => {
    setSelectedDocuments([]);
  };

  const handleApplyTemplate = (template: DocumentTemplate) => {
    // Per ora mostriamo solo un messaggio, in futuro applicheremo effettivamente il template
    showToast(`Template "${template.name}" selezionato. Funzionalità di applicazione template in sviluppo.`, "info");
  };

  const generateBatch = async () => {
    console.log('generateBatch called');
    console.log('Selected documents:', selectedDocuments);

    if (selectedDocuments.length === 0) {
      console.log('No documents selected, calling showToast');
      showToast('Seleziona almeno un documento da generare', 'info');
      return;
    }

    console.log('Proceeding with batch generation');
    setIsGenerating(true);
    setProgress({ current: 0, total: selectedDocuments.length, currentDoc: '' });

    // Track inizio generazione batch
    trackAnalyticsEvent('export_batch', 'batch_generation', {
      documentCount: selectedDocuments.length,
      documentTypes: selectedDocuments.map(d => d.type).join(', ')
    });

    console.log("generateBatch called", selectedDocuments);
    console.log("selectedDocuments state:", selectedDocuments);

    try {
      const generatedFiles: { name: string; blob: Blob }[] = [];

      for (let i = 0; i < selectedDocuments.length; i++) {
        const doc = selectedDocuments[i];
        setProgress({ current: i + 1, total: selectedDocuments.length, currentDoc: doc.title });

        let blob: Blob;
        let fileName: string;

        switch (doc.type) {
          case 'student_profile': {
            if (!isStudent(doc.data)) continue;
            const student = doc.data;
            const studentEvals = props.evaluations.filter(e => e.studenteId === student.id);
            const studentCompEvals = props.competencyEvaluations.filter(e => e.studenteId === student.id);
            blob = await generateStudentProfilePdf(student, studentEvals, studentCompEvals, props.settings);
            fileName = `Profilo_${student.cognome}_${student.nome}.pdf`;
            break;
          }

          case 'lesson_plan': {
            if (!isLesson(doc.data)) continue;
            const lesson = doc.data;
            blob = await generateLessonPdf(lesson);
            fileName = `Piano_Lezione_${lesson.id}.pdf`;
            break;
          }

          case 'uda': {
            if (!isUda(doc.data)) continue;
            const uda = doc.data;
            const udaHtml = `
              <h1>${uda.title}</h1>
              <p><strong>Classe:</strong> ${uda.classe}</p>
              <p><strong>Descrizione:</strong> ${uda.introduction || 'N/A'}</p>
              <p><strong>Obiettivi:</strong> ${uda.evaluation || 'N/A'}</p>
            `;
            blob = await generateHtmlDocxBlob(udaHtml, `UDA_${uda.title}`);
            fileName = `UDA_${uda.title.replace(/\s+/g, '_')}.docx`;
            break;
          }

          default:
            throw new Error(`Tipo documento non supportato: ${doc.type}`);
        }

        generatedFiles.push({ name: fileName, blob });

        // Track generazione documento
        trackAnalyticsEvent('document_generated', doc.type, {
          format: doc.format,
          source: 'batch_export'
        });
      }

      if (generatedFiles.length > 1) {
        const zip = new JSZip();
        generatedFiles.forEach(file => {
          zip.file(file.name, file.blob);
        });

        const zipBlob = await zip.generateAsync({ type: 'blob' });
        saveAs(zipBlob, 'Documenti_Export.zip');
      } else if (generatedFiles.length === 1) {
        saveAs(generatedFiles[0].blob, generatedFiles[0].name);
      }

      showToast(`Generati con successo ${generatedFiles.length} documenti!`, "success");
      props.onClose();

    } catch (error) {
      console.error("Errore generazione batch:", error);
      showToast("Errore durante la generazione dei documenti. Riprova.", "error");
    } finally {
      setIsGenerating(false);
      setProgress(null);
    }
  };

  const groupedDocuments = useMemo(() => {
    const groups: Record<string, BatchDocument[]> = {};
    availableDocuments.forEach(doc => {
      const groupKey = doc.type === 'student_profile' ? 'Profili Studente' :
                      doc.type === 'lesson_plan' ? 'Piani Lezione' :
                      doc.type === 'uda' ? 'UDA' : 'Altri';
      if (!groups[groupKey]) groups[groupKey] = [];
      groups[groupKey].push(doc);
    });
    return groups;
  }, [availableDocuments]);

  return (
    <M3Dialog
      title="Export Multiplo Documenti"
      onClose={props.onClose}
      maxWidth="2xl"
      level={1}
    >
      <M3DialogContent>
          {/* Progress Bar durante generazione */}
          {progress && (
            <div style={{ backgroundColor: layers.sys.color.onPrimary, borderRadius: layers.ref.shape.corner.large, padding: layers.ref.spacing['8'] }>
              <div style={{display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: layers.ref.spacing['8']}>
                <span  style={{ fontWeight: "500" }>Generazione in corso...</span>
                <span style={{ color:  layers.sys.color.onSurfaceVariant }>{progress.current}/{progress.total}</span>
              </div>
              <div style={{ backgroundColor: layers.sys.color.surfaceContainerHigh, width: "100%", borderRadius: layers.ref.spacing['4'], height: "0.5rem", marginBottom: layers.ref.spacing['8'] }>
                <div
                   style={{backgroundColor: "layers.sys.color.primary", height: "0.5rem", borderRadius: layers.ref.spacing['4'], transition: "all 300ms cubic-bezier(0.4, 0, 0.2, 1)", width: `${(progress.current / progress.total) * 100}%` }}
                ></div>
              </div>
              <p style={{ color: layers.sys.color.onSurfaceVariant, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }>{progress.currentDoc}</p>
            </div>
          )}

          {/* Controlli selezione */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }>
            <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8']}>
              <span  style={{ fontWeight: "500" }>
                Selezionati: {selectedDocuments.length} di {availableDocuments.length}
              </span>
              <div style={{display: "flex", gap: layers.ref.spacing['8']}>
                <M3Button onClick={selectAll} variant="text"  disabled={isGenerating}>
                  Seleziona Tutto
                </M3Button>
                <M3Button onClick={selectNone} variant="text"  disabled={isGenerating}>
                  Deseleziona Tutto
                </M3Button>
                <M3Button
                  onClick={() => {
                    setShowTemplateManager(true);
                    trackAnalyticsEvent('feature_usage', 'template_manager');
                  }}
                  variant="outlined"
                  
                  disabled={isGenerating}
                >
                  <span >description</span>
                  Template
                </M3Button>
              </div>
            </div>
          </div>

          {/* Lista documenti raggruppati */}
          <div  style={{gap: layers.ref.spacing['4'], overflowY: "auto"}>
            {Object.entries(groupedDocuments).map(([groupName, docs]) => (
              <div key={groupName}>
                <h3 style={{ color: layers.sys.color.onSurfaceVariant, fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: layers.ref.spacing['8'] }>
                  {groupName} ({docs.length})
                </h3>
                <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: layers.ref.spacing['8']}>
                  {docs.map(doc => {
                    const isSelected = selectedDocuments.some(d => d.id === doc.id);
                    return (
                      <div
                        key={doc.id}
                        className={`p-6 border rounded-[var(--md-sys-shape-corner-small)] cursor-pointer transition-all ${
                          isSelected
                            ? 'border-primary bg-primaryContainer/20'
                            : 'border-[var(--md-sys-color-outline-variant)] hover:border-primary/50'
                        }`}
                        onClick={() => !isGenerating && toggleDocumentSelection(doc.id)}
                      >
                        <div style={{display: "flex", alignItems: "flex-start", gap: layers.ref.spacing['6']}>
                          <input
                            type="checkbox"
                            checked={isSelected}
                            onChange={() => toggleDocumentSelection(doc.id)}
                            disabled={isGenerating}
                            
                            aria-label={`Seleziona ${doc.title}`}
                          />
                          <div style={{ flex: "1", minWidth: "0" }>
                            <p  style={{ fontWeight: "500", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }>{doc.title}</p>
                            <p style={{ color: layers.sys.color.onSurfaceVariant, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }>{doc.subtitle}</p>
                            <span className={`inline-block px-4 py-0.5 m3-label-small rounded-full mt-4 ${
                              doc.format === 'pdf' ? 'bg-error-container text-on-error-container' : 'bg-primaryContainer text-on-primaryContainer'
                            }`}>
                              {doc.format.toUpperCase()}
                            </span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
      </M3DialogContent>

      <M3DialogActions>
          <M3Button onClick={props.onClose} variant="text" disabled={isGenerating}>
            Annulla
          </M3Button>
          <M3Button
            onClick={generateBatch}
            variant="filled"
            disabled={isGenerating || selectedDocuments.length === 0}
          >
            {isGenerating ? `Generazione... (${progress?.current || 0}/${progress?.total || 0})` : `Genera ${selectedDocuments.length} Documenti`}
          </M3Button>
      </M3DialogActions>

      {/* Template Manager */}
      {showTemplateManager && (
        <TemplateManager
          onClose={() => setShowTemplateManager(false)}
          onApplyTemplate={handleApplyTemplate}
        />
      )}
    </M3Dialog>
  );
};

export default BatchExportWizard;

// MD3 Compliant - Migrated on 2024-12-19

import React, { useState, useMemo, useEffect, useRef } from 'react';
import '../modules.css';
import { EventoCalendario, AiSettings } from '../types';
import EventModal from './EventModal';
import AiEventParserModal from './AiEventParserModal';
import EventActionPopover from './EventActionPopover';
import { 

    M3Button, 
    TabGroup 
} from './ui';

interface CalendarProps {
    eventi: EventoCalendario[];
    setEventi: React.Dispatch<React.SetStateAction<EventoCalendario[]>>;
    aiSettings: AiSettings;
}

type CalendarView = 'month' | 'week' | 'day' | 'agenda';

const DAYS_SHORT = ['LUN', 'MAR', 'MER', 'GIO', 'VEN', 'SAB', 'DOM'];
const MONTHS_LONG = ['Gennaio', 'Febbraio', 'Marzo', 'Aprile', 'Maggio', 'Giugno', 'Luglio', 'Agosto', 'Settembre', 'Ottobre', 'Novembre', 'Dicembre'];

const Calendar: React.FC<CalendarProps> = ({ eventi, setEventi, aiSettings }) => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [viewMode, setViewMode] = useState<CalendarView>('month');
    const [editingEvent, setEditingEvent] = useState<Partial<EventoCalendario> | null>(null);
    const [isAiParserOpen, setIsAiParserOpen] = useState(false);
    const [popoverState, setPopoverState] = useState<{ event: EventoCalendario; anchorEl: HTMLElement } | null>(null);
    const [focusedDateIndex, setFocusedDateIndex] = useState<number>(0);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const calendarGridRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if ((viewMode === 'week' || viewMode === 'day') && scrollContainerRef.current) {
            const now = new Date();
            const hour = now.getHours();
            const scrollPos = Math.max(0, (hour - 1) * 60);
            scrollContainerRef.current.scrollTop = scrollPos;
        }
        // Reset focus when view changes
        setFocusedDateIndex(0);
    }, [viewMode]);

    const handleCalendarKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
        // Arrow key navigation for calendar grid (month view)
        if (viewMode !== 'month') return;

        const keysToHandle = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'];
        if (!keysToHandle.includes(e.key)) return;

        e.preventDefault();
        const totalDays = monthDates.length;
        const daysPerWeek = 7;
        let newIndex = focusedDateIndex;

        switch (e.key) {
            case 'ArrowLeft':
                newIndex = focusedDateIndex > 0 ? focusedDateIndex - 1 : 0;
                break;
            case 'ArrowRight':
                newIndex = focusedDateIndex < totalDays - 1 ? focusedDateIndex + 1 : totalDays - 1;
                break;
            case 'ArrowUp':
                newIndex = Math.max(0, focusedDateIndex - daysPerWeek);
                break;
            case 'ArrowDown':
                newIndex = Math.min(totalDays - 1, focusedDateIndex + daysPerWeek);
                break;
            case 'Home':
                newIndex = 0;
                break;
            case 'End':
                newIndex = totalDays - 1;
                break;
        }

        setFocusedDateIndex(newIndex);
    };

    const handleNavigate = (direction: 'prev' | 'next' | 'today') => {
        const newDate = new Date(currentDate);
        if (direction === 'today') {
            setCurrentDate(new Date());
            return;
        }

        const modifier = direction === 'next' ? 1 : -1;

        switch (viewMode) {
            case 'month':
                newDate.setMonth(currentDate.getMonth() + modifier);
                break;
            case 'week':
                newDate.setDate(currentDate.getDate() + (modifier * 7));
                break;
            case 'day':
                newDate.setDate(currentDate.getDate() + modifier);
                break;
            case 'agenda':
                newDate.setMonth(currentDate.getMonth() + modifier);
                break;
        }
        setCurrentDate(newDate);
    };

    const monthDates = useMemo(() => {
        const year = currentDate.getFullYear();
        const month = currentDate.getMonth();
        const firstDayOfMonth = new Date(year, month, 1);
        const startDayOfWeek = firstDayOfMonth.getDay();
        const daysFromPrevMonth = startDayOfWeek === 0 ? 6 : startDayOfWeek - 1;
        const startDate = new Date(firstDayOfMonth);
        startDate.setDate(startDate.getDate() - daysFromPrevMonth);
        const dates: Date[] = [];
        for (let i = 0; i < 42; i++) {
            const d = new Date(startDate);
            d.setDate(startDate.getDate() + i);
            dates.push(d);
        }
        return dates;
    }, [currentDate]);

    const weekDates = useMemo(() => {
        const startOfWeek = new Date(currentDate);
        const day = startOfWeek.getDay();
        const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
        startOfWeek.setDate(diff);
        startOfWeek.setHours(0, 0, 0, 0);
        
        const dates: Date[] = [];
        for (let i = 0; i < 7; i++) {
            const d = new Date(startOfWeek);
            d.setDate(startOfWeek.getDate() + i);
            dates.push(d);
        }
        return dates;
    }, [currentDate]);

    const dayEvents = useMemo(() => {
        return eventi.filter(e => e.data === currentDate.toISOString().split('T')[0]);
    }, [eventi, currentDate]);

    const agendaGroups = useMemo(() => {
        const sorted = [...eventi].sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime());
        const groups: Record<string, EventoCalendario[]> = {};
        sorted.forEach(ev => {
            const evDate = new Date(ev.data);
            if (viewMode === 'agenda') {
                const start = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
                const end = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);
                if (evDate >= start && evDate <= end) {
                    const key = ev.data;
                    if (!groups[key]) groups[key] = [];
                    groups[key].push(ev);
                }
            }
        });
        return groups;
    }, [eventi, currentDate, viewMode]);


    const renderHeader = () => {
        const title = viewMode === 'day'
            ? currentDate.toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' })
            : `${MONTHS_LONG[currentDate.getMonth()]} ${currentDate.getFullYear()}`;

        return (
            <header >
                <div >
                    <div style={{
                        backgroundColor: 'var(--md-sys-color-surface)',
                        padding: 'var(--md-sys-spacing-1)',
                        borderRadius: 'var(--md-sys-shape-corner-full)',
                        border: `1px solid var(--md-sys-color-outline)`
                    }>
                        <M3Button variant="text" onClick={() => handleNavigate('prev')} title="Mese precedente" aria-label="Vai al mese precedente" >
                            <span style={{
  fontFamily: 'Material Symbols Outlined'
} aria-hidden="true">chevron_left</span>
                        </M3Button>
                        <M3Button variant="tonal" onClick={() => handleNavigate('today')}  title="Torna a oggi">Oggi</M3Button>
                        <M3Button variant="text" onClick={() => handleNavigate('next')} title="Mese successivo" aria-label="Vai al mese successivo" >
                            <span style={{
  fontFamily: 'Material Symbols Outlined'
} aria-hidden="true">chevron_right</span>
                        </M3Button>
                    </div>
                    <h2 >{title}</h2>
                </div>

                <div  style={{gap: 'var(--md-sys-spacing-8)'}>
                    <TabGroup
                        tabs={[
                            { id: 'month', label: 'Mese' },
                            { id: 'week', label: 'Settimana' },
                            { id: 'day', label: 'Giorno' },
                            { id: 'agenda', label: 'Agenda' }
                        ]}
                        activeTab={viewMode}
                        onTabChange={(id) => setViewMode(id as CalendarView)}
                        variant="primary"
                    />

                    <div >
                        <M3Button variant="text" onClick={() => setIsAiParserOpen(true)} title="Analizza circolare con AI" aria-label="Apri analizzatore AI per circolari" >
                            <span style={{color: "var(--md-sys-color-primary)"} aria-hidden="true">auto_awesome</span>
                        </M3Button>
                        <M3Button variant="filled" onClick={() => setEditingEvent({})} title="Crea nuovo evento">
                            <span style={{
  fontFamily: 'Material Symbols Outlined'
} aria-hidden="true">add</span>
                            Nuovo Evento
                        </M3Button>
                    </div>
                </div>
            </header>
        );
    };

    const renderMonthView = () => (
        <div  role="grid" aria-label="Calendario mensile" ref={calendarGridRef} onKeyDown={handleCalendarKeyDown}>
            <div  role="row">
                {DAYS_SHORT.map(d => (
                    <div key={d}  role="columnheader" aria-label={d}>{d}</div>
                ))}
            </div>
            <div  role="rowgroup">
                {monthDates.map((date, i) => {
                    const isCurrentMonth = date.getMonth() === currentDate.getMonth();
                    const isToday = date.toDateString() === new Date().toDateString();
                    const dayEvents = eventi.filter(e => e.data === date.toISOString().split('T')[0]);
                    const isFocused = i === focusedDateIndex && viewMode === 'month';
                    
                    return (
                        <div 
                            key={i} 
                            style={{
                                padding: 'var(--md-sys-spacing-2)',
                                borderRadius: 'var(--md-sys-shape-corner-small)',
                                cursor: 'pointer',
                                position: 'relative',
                                opacity: !isCurrentMonth ? 0.5 : 1,
                                backgroundColor: isToday ? 'var(--md-sys-color-primary-container)' : 'transparent',
                                color: isToday ? 'var(--md-sys-color-on-primary-container)' : (!isCurrentMonth ? 'var(--md-sys-color-on-surface-variant)' : 'var(--md-sys-color-on-surface)'),
                                outline: isFocused ? `2px solid var(--md-sys-color-primary)` : 'none',
                                outlineOffset: isFocused ? '2px' : '0'
                            }
                            role="gridcell"
                            tabIndex={isFocused ? 0 : -1}
                            aria-label={`${date.toLocaleDateString('it-IT')}${dayEvents.length > 0 ? `, ${dayEvents.length} eventi` : ''}`}
                            onFocus={() => setFocusedDateIndex(i)}
                            onClick={() => {
                                setCurrentDate(date);
                                setViewMode('day');
                            }}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' || e.key === ' ') {
                                    e.preventDefault();
                                    setCurrentDate(date);
                                    setViewMode('day');
                                }
                            }}
                        >
                            <span >
                                {date.getDate()}
                            </span>
                            <div >
                                {dayEvents.slice(0, 3).map((ev, idx) => (
                                    <div 
                                        key={ev.id || idx} 
                                        style={{
                                            padding: 'var(--md-sys-spacing-1) var(--md-sys-spacing-2)',
                                            marginBottom: 'var(--md-sys-spacing-1)',
                                            borderRadius: 'var(--md-sys-shape-corner-small)',
                                            fontSize: 'var(--md-sys-typescale-body-small-size)',
                                            backgroundColor: ev.tipo === 'importante' ? 'var(--md-sys-color-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-secondary-container)' : 'var(--md-sys-color-primary-container)'),
                                            color: ev.tipo === 'importante' ? 'var(--md-sys-color-on-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-on-secondary-container)' : 'var(--md-sys-color-on-primary-container)'),
                                            cursor: 'pointer',
                                            whiteSpace: 'nowrap',
                                            overflow: 'hidden',
                                            textOverflow: 'ellipsis'
                                        }
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setEditingEvent(ev);
                                        }}
                                    >
                                        {ev.titolo}
                                    </div>
                                ))}
                                {dayEvents.length > 3 && (
                                    <div >+{dayEvents.length - 3} altri</div>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );

    const renderWeekView = () => (
        <div >
            <div >
                {weekDates.map((date, i) => {
                    const isToday = date.toDateString() === new Date().toDateString();
                    return (
                        <div key={i} style={{
                            padding: 'var(--md-sys-spacing-2)',
                            textAlign: 'center',
                            backgroundColor: isToday ? 'var(--md-sys-color-primary-container)' : 'var(--md-sys-color-surface-container-low)',
                            borderRadius: 'var(--md-sys-shape-corner-small)'
                        }>
                            <div style={{
                                fontSize: 'var(--md-sys-typescale-body-small-size)',
                                fontWeight: 'var(--md-sys-typescale-body-small-weight)',
                                color: isToday ? 'var(--md-sys-color-on-primary-container)' : 'var(--md-sys-color-on-surface-variant)',
                                marginBottom: 'var(--md-sys-spacing-1)'
                            }>
                                {DAYS_SHORT[i]}
                            </div>
                            <div style={{
                                fontSize: 'var(--md-sys-typescale-headline-small-size)',
                                fontWeight: 'var(--md-sys-typescale-headline-small-weight)',
                                color: isToday ? 'var(--md-sys-color-on-primary-container)' : 'var(--md-sys-color-on-surface)'
                            }>
                                {date.getDate()}
                            </div>
                        </div>
                    );
                })}
            </div>
            <div  ref={scrollContainerRef}>
                {Array.from({ length: 24 }, (_, hour) => (
                    <div key={hour} >
                        <div >
                            {hour.toString().padStart(2, '0')}:00
                        </div>
                        <div >
                            {weekDates.map((date, dayIndex) => {
                                const dayEvents = eventi.filter(e => {
                                    const eventDate = new Date(e.data);
                                    return eventDate.toDateString() === date.toDateString() &&
                                           e.oraInizio &&
                                           parseInt(e.oraInizio.split(':')[0]) === hour;
                                });
                                
                                return (
                                    <div key={dayIndex} >
                                        {dayEvents.map((ev, idx) => (
                                            <div 
                                                key={ev.id || idx} 
                                                style={{
                                                    padding: 'var(--md-sys-spacing-2)',
                                                    marginBottom: 'var(--md-sys-spacing-1)',
                                                    borderRadius: 'var(--md-sys-shape-corner-small)',
                                                    fontSize: 'var(--md-sys-typescale-body-small-size)',
                                                    backgroundColor: ev.tipo === 'importante' ? 'var(--md-sys-color-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-secondary-container)' : 'var(--md-sys-color-primary-container)'),
                                                    color: ev.tipo === 'importante' ? 'var(--md-sys-color-on-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-on-secondary-container)' : 'var(--md-sys-color-on-primary-container)'),
                                                    cursor: 'pointer',
                                                    border: '1px solid var(--md-sys-color-outline-variant)'
                                                }
                                                onClick={() => setEditingEvent(ev)}
                                            >
                                                <div >{ev.titolo}</div>
                                                <div >{ev.oraInizio} - {ev.oraFine || 'N/A'}</div>
                                            </div>
                                        ))}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );

    const renderDayView = () => (
        <div >
            <div  style={{padding: 'var(--md-sys-spacing-8)'}>
                <h3  style={{color: 'var(--md-sys-color-primary)'}>
                    {currentDate.toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                </h3>
            </div>
            <div  ref={scrollContainerRef}>
                {dayEvents.length === 0 ? (
                    <div style={{ 
                        padding: 'var(--md-sys-spacing-12)', 
                        display: "flex", 
                        flexDirection: "column", 
                        alignItems: "center", 
                        justifyContent: "center", 
                        textAlign: "center", 
                        opacity: "0.6" 
                    }>
                        <span 
                            style={{ 
                                color: 'var(--md-sys-color-on-surface-variant)',
                                marginBottom: 'var(--md-sys-spacing-8)'
                            } 
                            aria-hidden="true"
                        >
                            event_busy
                        </span>
                        <p style={{ color: 'var(--md-sys-color-on-surface' }>
                            Nessun evento per questo giorno
                        </p>
                        <M3Button variant="text" onClick={() => setEditingEvent({})} style={{marginTop: 'var(--md-sys-spacing-4)'}>
                            Aggiungi Evento
                        </M3Button>
                    </div>
                ) : (
                    <div  style={{padding: 'var(--md-sys-spacing-8)', gap: 'var(--md-sys-spacing-4)'}>
                        {dayEvents.map(ev => (
                            <div 
                                key={ev.id} 
                                style={{
                                    padding: 'var(--md-sys-spacing-4)',
                                    borderRadius: 'var(--md-sys-shape-corner-medium)',
                                    backgroundColor: ev.tipo === 'importante' ? 'var(--md-sys-color-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-secondary-container)' : 'var(--md-sys-color-primary-container)'),
                                    color: ev.tipo === 'importante' ? 'var(--md-sys-color-on-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-on-secondary-container)' : 'var(--md-sys-color-on-primary-container)'),
                                    cursor: 'pointer',
                                    transition: 'transform 0.2s ease-in-out',
                                    border: '1px solid var(--md-sys-color-outline-variant)'
                                }
                                onClick={() => setEditingEvent(ev)}
                                onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.01)'}
                                onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
                            >
                                <div  style={{ fontWeight: "bold" }>
                                    {ev.oraInizio || 'Tutto il giorno'}
                                </div>
                                <div >
                                    <div  style={{ fontWeight: "bold" }>{ev.titolo}</div>
                                    {ev.descrizione && <div  style={{ opacity: "0.8" }>{ev.descrizione}</div>}
                                    {ev.location && <div  style={{marginTop: 'var(--md-sys-spacing-4)'}>📍 {ev.location}</div>}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );

    const renderAgendaView = () => (
        <div  style={{padding: 'var(--md-sys-spacing-8)'}>
            {Object.keys(agendaGroups).length === 0 ? (
                <div style={{ padding: 'var(--md-sys-spacing-12)', display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", opacity: "0.6" }>
                    <span style={{ color: 'var(--md-sys-color-on-surface-variant)', marginBottom: 'var(--md-sys-spacing-8)' } aria-hidden="true">event_busy</span>
                    <p style={{ color: 'var(--md-sys-color-on-surface-variant)', fontSize: 'var(--md-sys-typescale-body-large-size)' }>Nessun evento questo mese</p>
                </div>
            ) : (
                <div style={{gap: 'var(--md-sys-spacing-6)'}>
                    {Object.entries(agendaGroups).map(([date, evts]) => (
                        <div key={date} style={{ backgroundColor: 'rgba(var(--md-sys-color-surface-container-high-rgb), 0.2)', borderRadius: 'var(--md-sys-shape-corner-medium)', padding: 'var(--md-sys-spacing-8)', border: "1px solid var(--md-sys-color-outline)" }>
                            <div  style={{color: "var(--md-sys-color-primary)", marginBottom: 'var(--md-sys-spacing-6)', borderBottom: "1px solid var(--md-sys-color-outline)"}>
                                {new Date(date).toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long' })}
                            </div>
                            <div  style={{gap: 'var(--md-sys-spacing-3)'}>
                                {evts.map(ev => (
                                    <div 
                                        key={ev.id} 
                                        style={{
                                            padding: 'var(--md-sys-spacing-3)',
                                            borderRadius: 'var(--md-sys-shape-corner-small)',
                                            backgroundColor: ev.tipo === 'importante' ? 'var(--md-sys-color-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-secondary-container)' : 'var(--md-sys-color-primary-container)'),
                                            color: ev.tipo === 'importante' ? 'var(--md-sys-color-on-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-on-secondary-container)' : 'var(--md-sys-color-on-primary-container)'),
                                            cursor: 'pointer',
                                            transition: 'background-color 0.2s ease-in-out',
                                            border: '1px solid var(--md-sys-color-outline-variant)'
                                        }
                                        onClick={() => setEditingEvent(ev)}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = ev.tipo === 'importante' ? 'color-mix(in srgb, var(--md-sys-color-error-container) 60%, var(--md-sys-color-surface-container-high))' : (ev.tipo === 'personale' ? 'color-mix(in srgb, var(--md-sys-color-secondary-container) 60%, var(--md-sys-color-surface-container-high))' : 'color-mix(in srgb, var(--md-sys-color-primary-container) 60%, var(--md-sys-color-surface-container-high))')}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = ev.tipo === 'importante' ? 'var(--md-sys-color-error-container)' : (ev.tipo === 'personale' ? 'var(--md-sys-color-secondary-container)' : 'var(--md-sys-color-primary-container)')}
                                    >
                                        <div  style={{ fontWeight: "bold" }>
                                            {ev.oraInizio || 'Tutto il giorno'}
                                        </div>
                                        <div >
                                            <div  style={{ fontWeight: "bold" }>{ev.titolo}</div>
                                            {ev.descrizione && <div  style={{ opacity: "0.8" }>{ev.descrizione}</div>}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );

    return (
        <div 
            
            ref={calendarGridRef}
            onKeyDown={handleCalendarKeyDown}
        >
            {renderHeader()}
            
            <div >
                {viewMode === 'month' && renderMonthView()}
                {viewMode === 'week' && renderWeekView()}
                {viewMode === 'day' && renderDayView()}
                {viewMode === 'agenda' && renderAgendaView()}
            </div>

            {editingEvent && (
                <EventModal
                    eventToEdit={editingEvent}
                    onClose={() => setEditingEvent(null)}
                    onSave={(ev) => {
                        if (ev.id) {
                            setEventi(prev => prev.map(e => e.id === ev.id ? ev : e));
                        } else {
                            setEventi(prev => [...prev, { ...ev, id: `evt-${Date.now()}` }]);
                        }
                        setEditingEvent(null);
                    }}
                    onDelete={(id) => {
                        setEventi(prev => prev.filter(e => e.id !== id));
                        setEditingEvent(null);
                    }}
                />
            )}

            {isAiParserOpen && (
                <AiEventParserModal
                    aiSettings={aiSettings}
                    onClose={() => setIsAiParserOpen(false)}
                    onEventParsed={(eventData: Partial<EventoCalendario>) => {
                        setEventi(prev => [...prev, { ...eventData, id: `evt-${Date.now()}` } as EventoCalendario]);
                        setIsAiParserOpen(false);
                    }}
                />
            )}

            {popoverState && (
                <EventActionPopover
                    event={popoverState.event}
                    anchorEl={popoverState.anchorEl}
                    onClose={() => setPopoverState(null)}
                    onEdit={() => {
                        setEditingEvent(popoverState.event);
                        setPopoverState(null);
                    }}
                    onDelete={() => {
                        setEventi(prev => prev.filter(e => e.id !== popoverState.event.id));
                        setPopoverState(null);
                    }}
                />
            )}
        </div>
    );
};

