            const levelMap: Record<string, { level: Livello; students: Studente[] }> = {};
            competency.livelli.forEach(level => {
                levelMap[level.id] = { level, students: [] };
            });

            classStudents.forEach(student => {
                const latestEval = competencyEvaluations
                    .filter(e => e.studenteId === student.id && e.competenzaId === competency.id)
                    .sort((a, b) => new Date(b.data).getTime() - new Date(a.data).getTime())[0];

                if (latestEval && levelMap[latestEval.livelloId]) {
                    levelMap[latestEval.livelloId].students.push(student);
                }
            });

            // Ensure consistent order A -> D
            const levelCounts = competency.livelli.map(level => ({
                level,
                count: levelMap[level.id].students.length,
                students: levelMap[level.id].students.sort((a, b) => a.cognome.localeCompare(b.cognome))
            }));

            const totalEvaluated = levelCounts.reduce((sum, lc) => sum + lc.count, 0);

            return { competency, levelCounts, totalEvaluated };
        });

        if (sortBy === 'performance') {
            summaries.sort((a, b) => {
                const getWeightedScore = (summary: CompetencySummary) => {
                    if (summary.totalEvaluated === 0) return 0;
                    return summary.levelCounts.reduce((score, lc) => {
                        const numericScore = parseInt(lc.level.punteggio || '0', 10);
                        return score + (numericScore * lc.count);
                    }, 0) / summary.totalEvaluated;
                };
                return getWeightedScore(b) - getWeightedScore(a); // Highest performance first
            });
        } else {
            summaries.sort((a,b) => a.competency.nome.localeCompare(b.competency.nome));
        }

        return summaries;
    }, [settings.competenze, classStudents, competencyEvaluations, sortBy]);

    const getLevelColorClass = (levelName: string) => {
        const lower = levelName.toLowerCase();
        if (lower.includes('avanzato') || lower.includes('a -')) return 'level-color-a';
        if (lower.includes('intermedio') || lower.includes('b -')) return 'level-color-b';
        if (lower.includes('base') || lower.includes('c -')) return 'level-color-c';
        if (lower.includes('iniziale') || lower.includes('d -')) return 'level-color-d';
        return 'level-color-none';
    };

    const handleLevelClick = (levelCount: CompetencySummary['levelCounts'][0], competencyName: string) => {
        if (levelCount.count > 0) {
            const colorClass = getLevelColorClass(levelCount.level.nome);
            setViewingStudents({
                title: `${competencyName} - Livello ${levelCount.level.nome}`,
                students: levelCount.students,
                levelColorClass: colorClass
            });
        }
    };
    
    return (
        <div style={{ minHeight: '100vh', backgroundColor: 'var(--md-sys-color-surface)' }>
            <div style={{ padding: 'var(--md-sys-spacing-6)', backgroundColor: 'var(--md-sys-color-surface-container)', borderBottom: '1px solid var(--md-sys-color-outline-variant)' }>
                <div style={{ maxWidth: '1200px', margin: '0 auto' }>
                    <h1 style={{ color: 'var(--md-sys-color-on-surface)', fontSize: 'var(--md-sys-typescale-headline-large-size)', fontWeight: 'var(--md-sys-typescale-headline-large-weight)', marginBottom: 'var(--md-sys-spacing-2)' }>Competenze {selectedClass}</h1>
                    <p style={{ color: 'var(--md-sys-color-on-surface-variant)' }>
                        Analisi dei livelli raggiunti per area di competenza.
                    </p>
                </div>
            </div>
            
            {/* Controls */}
            <div style={{display: "flex", justifyContent: "flex-end", marginBottom: layers.ref.spacing['8']}>
                <div style={{ backgroundColor: 'var(--md-sys-color-surface-container-high)', display: "flex", borderRadius: 'var(--md-sys-shape-corner-full)', padding: layers.ref.spacing['1'] }>
                    <button 
                        onClick={() => setSortBy('competency')} 
                        className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all ${sortBy === 'competency' ? 'bg-primary text-on-primary shadow-sm' : 'text-on-surface-variant hover:bg-surface-container-high'}`}
                    >
                        Alfabetico
                    </button>
                    <button 
                        onClick={() => setSortBy('performance')} 
                        className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all ${sortBy === 'performance' ? 'bg-primary text-on-primary shadow-sm' : 'text-on-surface-variant hover:bg-surface-container-high'}`}
                    >
                        Rendimento
                    </button>
                </div>
            </div>

            <div style={{marginTop: layers.ref.spacing['4']}>
                {competencySummaries.map(summary => {
                    const notEvaluatedCount = classStudents.length - summary.totalEvaluated;
                    return (
                        <details key={summary.competency.id} style={{ backgroundColor: 'var(--md-sys-color-surface-container-low)', borderRadius: 'var(--md-sys-shape-corner-medium)', border: "1px solid var(--md-sys-color-outline)", transition: "all 300ms cubic-bezier(0.4, 0, 0.2, 1)" }>
                            <summary  style={{padding: layers.ref.spacing['8'], cursor: "pointer"}>
                                {/* Custom Header Content */}
                                <div style={{display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: layers.ref.spacing['8'], marginBottom: layers.ref.spacing['6']}>
                                    <div style={{ flexGrow: "1", minWidth: "0" }>
                                        <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['8'], marginBottom: layers.ref.spacing['4']}>
                                            <span style={{ color: 'var(--md-sys-color-on-primary-container)', fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.05em", backgroundColor: "var(--md-sys-color-primary-container)", paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4'], borderRadius: "0.375rem", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }>
                                                {summary.competency.codice}
                                            </span>
                                            <span style={{ color: 'var(--md-sys-color-on-surface-variant)', fontSize: "0.75rem" }>
                                                {summary.totalEvaluated}/{classStudents.length} Valutati
                                            </span>
                                        </div>
                                        <h3 style={{ color: 'var(--md-sys-color-on-surface)', fontSize: "1.125rem", fontWeight: "bold" }>
                                            {summary.competency.nome}
                                        </h3>
                                    </div>
                                    <span style={{ color: 'var(--md-sys-color-on-surface-variant)', transition: "transform 300ms" }>expand_more</span>
                                </div>

                                {/* Visual Progress Bar */}
                                <div style={{ backgroundColor: 'var(--md-sys-color-surface-container-high)', height: "0.5rem", width: "100%", borderRadius: 'var(--md-sys-shape-corner-full)', display: "flex" }>
                                    {summary.levelCounts.map(lc => {
                                        if (lc.count === 0) return null;
                                        const pct = (lc.count / classStudents.length) * 100;
                                        const colorClass = getLevelColorClass(lc.level.nome);
                                        return (
                                            <div 
                                                key={lc.level.id} 
                                                className={`h-full ${colorClass}`} 
                                                style={{ width: `${pct}%` }} 
                                            />
                                        );
                                    })}
                                    {notEvaluatedCount > 0 && (
                                        <div 
                                            style={{ backgroundColor: 'var(--md-sys-color-surface-container-high)', height: "100%", width: `${(notEvaluatedCount / classStudents.length) * 100}%` }}
                                        />
                                    )}
                                </div>
                            </summary>
                            
                            <div  style={{padding: layers.ref.spacing['8'], paddingTop: "0", display: "grid", gridTemplateColumns: "1fr", gap: layers.ref.spacing['6']}>
                                {summary.levelCounts.map(lc => {
                                    const colorClass = getLevelColorClass(lc.level.nome);
                                    return (
                                        <div 
                                            key={lc.level.id} 
                                            onClick={() => handleLevelClick(lc, summary.competency.nome)}
                                            className={`p-8 rounded-[var(--md-sys-shape-corner-large)] border transition-all ${lc.count === 0 ? 'opacity-40 grayscale border-[var(--md-sys-color-outline-variant)]' : 'cursor-pointer border-[var(--md-sys-color-outline-variant)] hover:bg-[var(--md-sys-color-surface-container-high)] hover:border-primary/30'}`}
                                        >
                                            <div style={{display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: layers.ref.spacing['8']}>
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-white font-bold ${colorClass}`}>
                                                    {lc.level.nome.charAt(0)}
                                                </div>
                                                <div style={{ color: 'var(--md-sys-color-on-surface)', fontSize: "1.5rem", fontWeight: "900" }>{lc.count}</div>
                                            </div>
                                            <div style={{ color: 'var(--md-sys-color-on-surface-variant)', fontWeight: "bold", textTransform: "uppercase", marginBottom: layers.ref.spacing['4'] }>Studenti</div>
                                            <p style={{ color: 'var(--md-sys-color-on-surface-variant)', fontSize: "0.75rem", lineHeight: "1.625" }>
                                                {lc.level.descrizione}
                                            </p>
                                        </div>
                                    );
                                })}
                            </div>
                        </details>
                    );
                })}
                
                {competencySummaries.length === 0 && (
                    <div style={{ padding: 'var(--md-sys-spacing-12)', backgroundColor: 'var(--md-sys-color-surface-container-low)', borderRadius: 'var(--md-sys-shape-corner-medium)', display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center" }>
                        <span style={{ color: 'var(--md-sys-color-on-surface-variant)', opacity: 0.3, marginBottom: layers.ref.spacing['8'] }>bar_chart</span>
                        <p style={{ color: 'var(--md-sys-color-on-surface)', fontSize: "1.25rem", fontWeight: "bold" }>Nessun dato</p>
                        <p style={{ color: 'var(--md-sys-color-on-surface-variant)' }>Non hai ancora configurato le competenze in Impostazioni.</p>
                    </div>
                )}
            </div>

            {/* Student List Modal */}
            {viewingStudents && (
                <M3Dialog
                    title={viewingStudents.title}
                    onClose={() => setViewingStudents(null)}
                    maxWidth="md"
                >
                    <M3DialogContent style={{gap: layers.ref.spacing['2']}>
                                {viewingStudents.students.map(student => {
                                     return (
                                        <div 
                                            key={student.id} 
                                            onClick={() => { setViewingStudents(null); onViewStudentProfile(student); }} 
                                            style={{ backgroundColor: 'var(--md-sys-color-surface-container-low)', borderRadius: 'var(--md-sys-shape-corner-medium)', display: "flex", alignItems: "center", justifyContent: "space-between", padding: layers.ref.spacing['8'], border: "1px solid var(--md-sys-color-outline)", cursor: "pointer", transition: "all 300ms cubic-bezier(0.4, 0, 0.2, 1)" }
                                        >
                                            <div style={{display: "flex", alignItems: "center", gap: layers.ref.spacing['6']}>
                                                <Avatar name={`${student.nome} ${student.cognome}`} size="md" />
                                                <div>
                                                    <p style={{ color: 'var(--md-sys-color-on-surface)', fontWeight: "bold" }>{student.cognome} {student.nome}</p>
                                                    <div  style={{ display: "flex", alignItems: "center" }>
                                                        <span className={`w-2 h-2 rounded-full ${viewingStudents.levelColorClass}`}></span>
                                                        <span style={{ color: 'var(--md-sys-color-on-surface-variant)', fontSize: "0.75rem" }>Livello raggiunto</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <span style={{ color: 'var(--md-sys-color-on-surface-variant)', transition: "transform 300ms" }>arrow_forward</span>
                                        </div>
                                    )
                                })}
                    </M3DialogContent>
                    <M3DialogActions>
                        <M3Button onClick={() => setViewingStudents(null)} variant="text">Chiudi</M3Button>
                    </M3DialogActions>
                </M3Dialog>
            )}
        </div>
    );
};

