import React, { useState, useMemo } from 'react';
import { Studente, Valutazione, TimetableSettings, AiSettings, Report, ValutazioneCompetenza, PeriodoValutazione } from '../types';
import { generateCouncilDataPdf, viewPdfInNewTab } from '../utils/documentUtils';
import { useTheme } from '../theme/theme';
import { 

    M3Dialog, 
    M3DialogContent, 
    M3DialogActions, 
    M3Button, 
    TabGroup, 
    SelectField, 
    InfoCard 
} from './ui';

interface ConsiglioClasseWizardProps {
    onClose: () => void;
    userClasses: string[];
    students: Studente[];
    evaluations: Valutazione[];
    competencyEvaluations: ValutazioneCompetenza[];
    settings: TimetableSettings;
    aiSettings: AiSettings;
    onSaveReport: (report: Report) => void;
}

const ConsiglioClasseWizard: React.FC<ConsiglioClasseWizardProps> = (props) => {
  const { layers } = useTheme();
    const [step, setStep] = useState<1 | 2>(1);
    const [selectedClass, setSelectedClass] = useState<string>(props.userClasses[0] || '');
    const [periodo, setPeriodo] = useState<PeriodoValutazione>('primo-quadrimestre');
    const [isLoading, setIsLoading] = useState(false);
    const [loadingMessage, setLoadingMessage] = useState('');

    const classStudents = useMemo(() => {
        return props.students.filter(s => s.classe === selectedClass);
    }, [selectedClass, props.students]);
    
    const handleGeneratePdf = async () => {
        if (!selectedClass) return;
        setIsLoading(true);
        setLoadingMessage('Aggregazione dati e creazione PDF...');
        try {
            const blob = await generateCouncilDataPdf(
                selectedClass,
                periodo,
                classStudents,
                props.evaluations,
                props.competencyEvaluations,
                props.settings
            );
            viewPdfInNewTab(blob);
            props.onClose();
        } catch (error) {
            console.error("PDF generation failed", error);
            alert("Errore durante la generazione del PDF.");
        } finally {
            setIsLoading(false);
        }
    };

    const renderStep1 = () => (
        <>
            <M3DialogContent style={{gap: layers.ref.spacing['6']}>
                <InfoCard 
                    title="Seleziona il contesto" 
                    description="Scegli la classe e il periodo di riferimento per il quale desideri generare il report." 
                    icon="tune"
                    variant="surface"
                    
                />
                
                <SelectField 
                    id="council-class-select"
                    label="Classe" 
                    value={selectedClass} 
                    onChange={e => setSelectedClass(e.target.value)}
                >
                    {props.userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                </SelectField>

                 <div style={{gap: layers.ref.spacing['2']}>
                    <label  style={{color: "layers.sys.color.primary", fontWeight: "900", textTransform: "uppercase", paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4']}>Periodo di Valutazione</label>
                    <TabGroup
                        tabs={[
                            { id: 'primo-quadrimestre', label: 'Primo Quadrimestre (1Q)' },
                            { id: 'secondo-quadrimestre', label: 'Scrutinio Finale (2Q)' }
                        ]}
                        activeTab={periodo}
                        onTabChange={(id) => setPeriodo(id as PeriodoValutazione)}
                        variant="primary"
                        style={{ width: "100%" }
                    />
                </div>
            </M3DialogContent>
            <M3DialogActions>
                <M3Button variant="text" onClick={props.onClose}>Annulla</M3Button>
                <M3Button 
                    variant="filled" 
                    onClick={() => setStep(2)} 
                    disabled={!selectedClass}
                    endIcon={<span style={{
  fontFamily: 'Material Symbols Outlined'
}>arrow_forward</span>}
                >
                    Continua
                </M3Button>
            </M3DialogActions>
        </>
    );

    const renderStep2 = () => (
        <>
            <M3DialogContent style={{gap: layers.ref.spacing['6']}>
                <div style={{ backgroundColor: sys.colors.primaryContainer/20, borderRadius: layers.ref.shape.corner.large , {padding: layers.ref.spacing['5'], border: "1px solid layers.sys.color.outline", display: "flex", alignItems: "center", justifyContent: "space-between"}>
                    <div>
                        <p style={{fontWeight: "900", textTransform: "uppercase", letterSpacing: "0.1em", color: "layers.sys.color.primary"}>Context Active</p>
                        <h3 style={{ color:  layers.sys.color.onPrimary , { fontWeight: "900" }>
                    </div>
                    <M3Button variant="tonal" onClick={() => setStep(1)}  style={{ fontSize: "0.75rem", fontWeight: "bold", textTransform: "uppercase" }>Cambia</M3Button>
                </div>

                <div  style={{gap: layers.ref.spacing['3']}>
                    <button onClick={handleGeneratePdf} style={{ borderRadius: layers.ref.shape.corner.large , { transition: "all 300ms cubic-bezier(0.4, 0, 0.2, 1)", width: "100%", textAlign: "left" }>
                        <div ><span  style={{ transition: "transform 300ms" }>picture_as_pdf</span></div>
                        <div >
                            <p >Tabellone Dati (PDF)</p>
                            <p >Medie, trend e rilevazioni competenze.</p>
                        </div>
                    </button>
                </div>
                
                <p style={{ color:  layers.sys.color.onSurfaceVariant , {textAlign: "center", paddingLeft: layers.ref.spacing['4'], paddingRight: layers.ref.spacing['4']}>
                    Il report verrà generato e aperto in una nuova scheda del browser.
                </p>
            </M3DialogContent>
            <M3DialogActions>
                <M3Button variant="text" onClick={() => setStep(1)}>Indietro</M3Button>
            </M3DialogActions>
        </>
    );
    
    if (isLoading) {
        return (
             <M3Dialog
                 onClose={() => {}}
                 title=""
                 maxWidth="sm"
             >
                <M3DialogContent  style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center" }>
                    <div  style={{borderRadius: layers.ref.spacing['4'], height: layers.ref.spacing['4'], width: layers.ref.spacing['4'], borderBottom: "4px solid layers.sys.color.outline", borderColor: "layers.sys.color.primary", marginBottom: layers.ref.spacing['6']}></div>
                    <p  style={{fontWeight: "900", color: "layers.sys.color.primary"}>{loadingMessage}</p>
                </M3DialogContent>
            </M3Dialog>
        )
    }

    return (
        <M3Dialog
            onClose={props.onClose}
            title="Wizard Report Consiglio"
            maxWidth="xl"
        >
            {step === 1 ? renderStep1() : renderStep2()}
        </M3Dialog>
    );
};

