import { AiSettings, Corpus, ChatMessage, KnowledgeBaseEntry } from '../types';
import { generateAnswerFromCorpus } from '../services/aiService';
import { M3IconButton, M3Typography } from './ui';

// MD3 Pure: Migrated to inline styles using MD3 tokens for chat interface, message bubbles, and input controls
// All corpus-chat-* classes removed in favor of token-based styling

// Add this CSS animation to your global styles or component:
// @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
interface CorpusChatProps {
    corpus: Corpus;
    aiSettings: AiSettings;
    onClose: () => void;
    knowledgeBase: KnowledgeBaseEntry[];
    setCorpora: React.Dispatch<React.SetStateAction<Corpus[]>>;
}

const CorpusChat: React.FC<CorpusChatProps> = ({ corpus, aiSettings, onClose, knowledgeBase, setCorpora }) => {
    const [messages, setMessages] = useState<ChatMessage[]>(corpus.chatHistory || []);
    const [chatInput, setChatInput] = useState('); // FIX: Define chatInput
    const [isLoading, setIsLoading] = useState(false); // FIX: Consistent naming with isLoading
    
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Sync local state back to the main state whenever messages change
    useEffect(() => {
        // Only update if the local state is different from the prop to avoid loops
        if (messages !== corpus.chatHistory) {
            setCorpora(prevCorpora => 
                prevCorpora.map(c => 
                    c.id === corpus.id ? { ...c, chatHistory: messages } : c
                )
            );
        }
    }, [messages, corpus.id, corpus.chatHistory, setCorpora]);

    // FIX: Re-initialize messages when selectedCorpus or its chatHistory changes
    useEffect(() => {
        setMessages(corpus.chatHistory || []);
    }, [corpus]);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, messagesEndRef]);

    const handleSendMessage = async (text: string) => {
        if (!text.trim() || !corpus || isLoading) return; // FIX: Use 'corpus' prop directly and 'isLoading'
        
        const userMessage: ChatMessage = { role: 'user', text };
        const updatedHistory = [...messages, userMessage]; // FIX: Define updatedHistory
        setMessages(updatedHistory);
        setChatInput(');
        setIsLoading(true);

        try {
            const corpusFiles = knowledgeBase.filter(e => e.corpusId === corpus.id);
            if (corpusFiles.length === 0) {
                 throw new Error("Questo set di documenti è vuoto. Aggiungi dei file per poter chattare.");
            }
            const corpusContent = corpusFiles.map(e => `--- Contenuto da: ${e.fileName} ---\n${e.content}`).join('\n\n');
            const modelResponse = await generateAnswerFromCorpus(aiSettings, corpusContent, text); // FIX: Use 'text' parameter here
            setMessages(prev => [...prev, modelResponse]); // Update local state directly

        } catch (error) {
            const errorMsg = error instanceof Error ? error.message : 'Riprova.';
            console.error("Error generating answer from corpus:", errorMsg);
            const errorMessage: ChatMessage = {
                role: 'model',
                text: `Si è verificato un errore: ${errorMsg}`
            };
            setMessages(prev => [...prev, errorMessage]);
        } finally {
            setIsLoading(false);
        }
    };
    
    const handleShortcut = (prompt: string) => {
        handleSendMessage(prompt);
    }

    return (
        <div style={{display: 'flex',
            flexDirection: 'column',
            height: '100vh',
            backgroundColor: var(--md-sys-color-surface),
            margin: '0 auto'}>
            <div style={{display: 'flex',
                alignItems: 'center',
                padding: var(--md-sys-spacing-4),
                backgroundColor: var(--md-sys-color-surfaceContainerLow),
                borderBottom: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                gap: var(--md-sys-spacing-3)}}>
                <M3IconButton 
                    icon="arrow_back" 
                    onClick={onClose} 
                    ariaLabel="Torna alla lista"
                />
                <div style={{display: 'flex',
                    alignItems: 'center',
                    gap: var(--md-sys-spacing-3),
                    minWidth: 0,
                    flex: 1}>
                    <div style={{borderRadius: var(--md-sys-shape-corner-large),
                        backgroundColor: var(--md-sys-color-primaryContainer),
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'}>
                        <span style={{
  fontFamily: 'Material Symbols Outlined'
} style={{color: var(--md-sys-color-onPrimaryContainer)}>chat</span>
                    </div>
                    <M3Typography variant="title-large" style={{color: var(--md-sys-color-onSurface),
                        minWidth: 0,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'}>Chat con "{corpus.displayName}"</M3Typography>
                </div>
            </div>
            
            <div style={{flex: 1,
                overflowY: 'auto',
                padding: var(--md-sys-spacing-4),
                display: 'flex',
                flexDirection: 'column',
                gap: var(--md-sys-spacing-3)}>
                {messages.map((msg, index) => (
                    <div key={index} style={{display: 'flex',
                        justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start',
                        marginBottom: var(--md-sys-spacing-2)}>
                        <div style={{maxWidth: '70%',
                            padding: var(--md-sys-spacing-3),
                            borderRadius: msg.role === 'user' 
                                ? `${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-small)} ${var(--md-sys-shape-corner-large)}`
                                : `${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-small)}`,
                            backgroundColor: msg.role === 'user' 
                                ? var(--md-sys-color-primaryContainer) 
                                : var(--md-sys-color-surfaceContainerHigh),
                            border: `1px solid ${var(--md-sys-color-outlineVariant)}`}}>
                            <M3Typography variant="body-large" style={{color: msg.role === 'user' 
                                    ? var(--md-sys-color-onPrimaryContainer) 
                                    : var(--md-sys-color-onSurface),
                                margin: 0}>{msg.text}</M3Typography>
                        </div>
                    </div>
                ))}
                {isLoading && (
                     <div style={{display: 'flex',
                        justifyContent: 'flex-start',
                        marginBottom: var(--md-sys-spacing-2)}>
                        <div style={{maxWidth: '70%',
                            padding: var(--md-sys-spacing-3),
                            borderRadius: `${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-large)} ${var(--md-sys-shape-corner-small)}`,
                            backgroundColor: var(--md-sys-color-surfaceContainerHigh),
                            border: `1px solid ${var(--md-sys-color-outlineVariant)}`}}>
                            <div style={{display: 'flex',
                                alignItems: 'center',
                                gap: var(--md-sys-spacing-2)}>
                                <div style={{borderRadius: '50%'} />
                                <M3Typography variant="body-medium" style={{color: var(--md-sys-color-onSurfaceVariant),
                                    margin: 0}>Sto pensando...</M3Typography>
                            </div>
                        </div>
                    </div>
                )}
                 {messages.length === 0 && !isLoading && (
                    <div style={{display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flex: 1,
                        padding: var(--md-sys-spacing-8),
                        textAlign: 'center',
                        gap: var(--md-sys-spacing-4)}>
                        <div style={{borderRadius: var(--md-sys-shape-corner-large),
                            backgroundColor: var(--md-sys-color-secondaryContainer),
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center'}>
                            <span style={{
  fontFamily: 'Material Symbols Outlined'
} style={{color: var(--md-sys-color-onSecondaryContainer)}>quiz</span>
                        </div>
                        <M3Typography variant="body-large" style={{color: var(--md-sys-color-onSurfaceVariant),
                            margin: 0}>Poni una domanda ai documenti in questo set.</M3Typography>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            <div style={{padding: var(--md-sys-spacing-4),
                borderTop: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                backgroundColor: var(--md-sys-color-surfaceContainerLow)}}>
                <div style={{display: 'flex',
                    gap: var(--md-sys-spacing-2),
                    flexWrap: 'wrap'}>
                    <button 
                        onClick={() => handleShortcut("Crea un riassunto dettagliato dei documenti forniti.")} 
                        style={{display: 'flex',
                            alignItems: 'center',
                            gap: var(--md-sys-spacing-2),
                            padding: var(--md-sys-spacing-3),
                            backgroundColor: var(--md-sys-color-secondaryContainer),
                            border: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                            borderRadius: var(--md-sys-shape-corner-large),
                            cursor: 'pointer',
                            transition: `all ${200ms} ${cubic-bezier(0.4, 0, 0.2, 1)}`,
                            textDecoration: 'none'}}
                        onMouseEnter={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                    >
                        <span style={{
  fontFamily: 'Material Symbols Outlined'
} style={{color: var(--md-sys-color-onSecondaryContainer)}>summarize</span>
                        <M3Typography variant="label-large" style={{color: var(--md-sys-color-onSecondaryContainer),
                            margin: 0}>Riassumi</M3Typography>
                    </button>
                    <button 
                        onClick={() => handleShortcut("Genera 5 domande a risposta multipla con 4 opzioni ciascuna (indicando la risposta corretta) basandoti sui documenti.")} 
                        style={{display: 'flex',
                            alignItems: 'center',
                            gap: var(--md-sys-spacing-2),
                            padding: var(--md-sys-spacing-3),
                            backgroundColor: var(--md-sys-color-tertiaryContainer),
                            border: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                            borderRadius: var(--md-sys-shape-corner-large),
                            cursor: 'pointer',
                            transition: `all ${200ms} ${cubic-bezier(0.4, 0, 0.2, 1)}`,
                            textDecoration: 'none'}}
                        onMouseEnter={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                    >
                        <span style={{
  fontFamily: 'Material Symbols Outlined'
} style={{color: var(--md-sys-color-onTertiaryContainer)}>quiz</span>
                        <M3Typography variant="label-large" style={{color: var(--md-sys-color-onTertiaryContainer),
                            margin: 0}>Crea Quiz</M3Typography>
                    </button>
                    <button 
                        onClick={() => handleShortcut("Estrai i 5 concetti chiave da questi documenti e descrivili brevemente.")} 
                        style={{display: 'flex',
                            alignItems: 'center',
                            gap: var(--md-sys-spacing-2),
                            padding: var(--md-sys-spacing-3),
                            backgroundColor: var(--md-sys-color-primaryContainer),
                            border: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                            borderRadius: var(--md-sys-shape-corner-large),
                            cursor: 'pointer',
                            transition: `all ${200ms} ${cubic-bezier(0.4, 0, 0.2, 1)}`,
                            textDecoration: 'none'}}
                        onMouseEnter={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget// removed runtime mutation
                            e.currentTarget// removed runtime mutation
                        }}
                    >
                        <span style={{
  fontFamily: 'Material Symbols Outlined'
} style={{color: var(--md-sys-color-onPrimaryContainer)}>key</span>
                        <M3Typography variant="label-large" style={{color: var(--md-sys-color-onPrimaryContainer),
                            margin: 0}>Concetti Chiave</M3Typography>
                    </button>
                </div>
            </div>

            <form 
                onSubmit={(e) => { e.preventDefault(); handleSendMessage(chatInput); }}
                style={{display: 'flex',
                    padding: var(--md-sys-spacing-4),
                    backgroundColor: var(--md-sys-color-surfaceContainerLow),
                    borderTop: `1px solid ${var(--md-sys-color-outlineVariant)}`,
                    gap: var(--md-sys-spacing-2)}}
            >
                <input
                    type="text"
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    placeholder="Fai una domanda..."
                    style={{flex: 1,
                        padding: `${var(--md-sys-spacing-3)} ${var(--md-sys-spacing-4)}`,
                        borderRadius: var(--md-sys-shape-corner-large),
                        border: `1px solid ${var(--md-sys-color-outline)}`,
                        backgroundColor: var(--md-sys-color-surfaceContainerHigh),
                        color: var(--md-sys-color-onSurface),
                        outline: 'none',
                        transition: `border-color ${200ms} ${cubic-bezier(0.4, 0, 0.2, 1)}`}}
                    onFocus={(e) => {
                        e.target// removed runtime mutation
                    }}
                    onBlur={(e) => {
                        e.target// removed runtime mutation
                    }}
                    disabled={isLoading}
                />
                <button 
                    type="submit" 
                    disabled={isLoading || !chatInput.trim()}
                    style={{borderRadius: var(--md-sys-shape-corner-large),
                        border: 'none',
                        backgroundColor: (isLoading || !chatInput.trim()) 
                            ? var(--md-sys-color-surfaceContainerHigh) 
                            : var(--md-sys-color-primary),
                        color: (isLoading || !chatInput.trim()) 
                            ? var(--md-sys-color-onSurfaceVariant) 
                            : var(--md-sys-color-onPrimary),
                        cursor: (isLoading || !chatInput.trim()) ? 'not-allowed' : 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        transition: `all ${200ms} ${cubic-bezier(0.4, 0, 0.2, 1)}`}}
                >
                    <span style={{
  fontFamily: 'Material Symbols Outlined'
}>send</span>
                </button>
            </form>
        </div>
    );
};

export default CorpusChat;

// LEGACY - MD3 Non-compliant
import React, { useState, useEffect, useMemo } from 'react';
import { Lezione, AiSettings, Studente, PianoInclusione, Slot, CurriculumSubject } from '../types';
import { generateInclusivityAdaptations } from '../services/aiService';
import { DAYS_OF_WEEK } from '../constants';
import { parseClassString } from '../utils/schoolUtils'; 
import { TextField, SelectField, TextArea, M3Dialog, M3DialogContent, M3DialogActions, M3Button, AiThinkingGem } from './ui';
import { useTheme } from '../theme/theme';

interface CreateLessonFromAiModalProps {
    content: { title: string; htmlContent: string };
    onClose: () => void;
    onSave: (lessonData: Omit<Lezione, 'id' | 'svolta'>) => void;
    userClasses: string[];
    disciplines: string[];
    students: Studente[];
    pianiInclusione: Record<string, PianoInclusione>;
    aiSettings: AiSettings;
    slots?: Record<string, Slot>;
    onSchedule?: (lesson: Lezione, slotKey: string) => void;
    curricula: CurriculumSubject[]; 
}

const CreateLessonFromAiModal: React.FC<CreateLessonFromAiModalProps> = ({ content, onClose, onSave, userClasses, disciplines, students, pianiInclusione, aiSettings, slots, onSchedule, curricula }) => {
  const { layers } = useTheme();
    const [argomento, setArgomento] = useState('');
    const [obiettivi, setObiettivi] = useState('');
    const [classe, setClasse] = useState(userClasses[0] || '');
    const [materia, setMateria] = useState(disciplines[0] || '');
    const [adattamenti, setAdattamenti] = useState('');
    const [isAdaptationsLoading, setIsAdaptationsLoading] = useState(false);
const [selectedSlotKey, setSelectedSlotKey] = useState<string>('');
    
    // Objective Picker State
    const [isObjectivePickerOpen, setIsObjectivePickerOpen] = useState(false);

    useEffect(() => {
        // AI-powered pre-fill
        setArgomento(content.title);

        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = content.htmlContent;
        
        let extractedObjectives = '';
        // Try to find a list, which is a good candidate for objectives
        const list = tempDiv.querySelector('ul, ol');
        if (list) {
            extractedObjectives = Array.from(list.querySelectorAll('li'))
                .map(li => `- ${li.textContent?.trim()}`)
                .join('\n');
        } else {
            // Fallback: take the first few lines of text
            extractedObjectives = (tempDiv.textContent || '')
                .split('\n')
                .filter(line => line.trim().length > 10) // Filter out short/empty lines
                .slice(0, 3)
                .map(line => `- ${line.trim()}`)
                .join('\n');
        }
        setObiettivi(extractedObjectives);

    }, [content]);

    // Find free slots for the selected class
    const availableSlots = useMemo(() => {
        if (!slots || !classe) return [];
        // FIX: Casting esplicito di entries per TS
        const entries = Object.entries(slots) as [string, Slot][];
        return entries
            .filter(([, slot]) => !slot.lezioneId && (!slot.classe || slot.classe === classe)) // Filter out already assigned slots
            .sort((a: [string, Slot], b: [string, Slot]) => {
                const dayOrder = DAYS_OF_WEEK.indexOf(a[1].giorno) - DAYS_OF_WEEK.indexOf(b[1].giorno);
                if (dayOrder !== 0) return dayOrder;
                return a[1].ora.localeCompare(b[1].ora);
            })
            .slice(0, 4); // Show only a few for quick selection
    }, [slots, classe]);

    // Logic to find matching curriculum
    const matchingCurriculum = useMemo(() => {
        if (!classe || !materia || !curricula) return null;
        
        // 1. Try exact match on subject
        const subjectMatch = curricula.filter(c => c.subject === materia);
        if (subjectMatch.length === 0) return null;

        // 2. Try to match grade level (e.g. "1A" -> "1" or "Prime")
        const parsed = parseClassString(classe);
        if (!parsed) return subjectMatch[0]; // Fallback to first

        // Fuzzy match grade level string
        return subjectMatch.find(c => {
            const gradeStr = parsed.grade.toString();
            return c.gradeLevel.includes(gradeStr) || 
                   (parsed.grade === 1 && c.gradeLevel.toLowerCase().includes('prime')) ||
                   (parsed.grade === 2 && c.gradeLevel.toLowerCase().includes('seconde')) ||
                   (parsed.grade === 3 && c.gradeLevel.toLowerCase().includes('terze')) ||
                   (parsed.grade === 4 && c.gradeLevel.toLowerCase().includes('quarte')) ||
                   (parsed.grade === 5 && c.gradeLevel.toLowerCase().includes('quinte'));
        }) || subjectMatch[0];

    }, [curricula, classe, materia]);

    const handleAddObjective = (text: string) => {
        setObiettivi(prev => {
            const prefix = prev.trim() ? '\n' : '; ';
            return `${prev}${prefix}- ${text}`;
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!argomento.trim() || !classe || !materia) {
            alert('Per favore, compila Argomento, Classe e Materia.');
            return;
        }
        
        const lessonData: Omit<Lezione, 'id' | 'svolta'> = {
            contenuto: argomento,
            obiettivi,
            classe,
            materia,
            adattamenti,
            tipoLezione: 'Teoria', // Default type
            compiti: '',
        };

        if (selectedSlotKey && onSchedule) {
            const fullLesson: Lezione = {
                ...lessonData,
                id: `lesson-ai-${Date.now()}`,
                svolta: false
            };
            onSchedule(fullLesson, selectedSlotKey);
        } else {
            onSave(lessonData);
        }
        onClose();
    };

    const handleGenerateAdaptations = async () => {
        if (!classe || !argomento) {
            alert("Definisci la classe e l'argomento della lezione prima di chiedere suggerimenti.");
            return;
        }
    
        setIsAdaptationsLoading(true);
        try {
            const pianiInclusionePerClasse = (Object.values(pianiInclusione) as PianoInclusione[]).filter(p => {
                const student = students.find(s => s.id === p.id);
                return student && student.classe === classe;
            });
    
            if (pianiInclusionePerClasse.length === 0) {
                alert("Nessun Piano di Inclusione attivo trovato per questa classe. Aggiungine uno dalla sezione 'Didattica Inclusiva' per ricevere suggerimenti mirati.");
                return; 
            }
    
            const lessonContext = {
                contenuto: argomento,
                classe: classe,
            };
    
            const adaptations = await generateInclusivityAdaptations(aiSettings, lessonContext, pianiInclusionePerClasse);
            
            setAdattamenti(prev => prev ? `${prev}\n${adaptations}` : adaptations);
    
        } catch (error) {
            const errorMsg = error instanceof Error ? error.message : 'Errore sconosciuto';
            console.error("Error generating inclusivity adaptations:", errorMsg);
            alert("Si è verificato un errore durante la generazione dei suggerimenti per l'inclusività.");
        } finally {
            setIsAdaptationsLoading(false);
        }
    };


    return (
        <>
            <M3Dialog
                title="Crea Bozza Lezione"
                onClose={onClose}
                maxWidth="lg"
                level={1}
            >
                <form id="create-lesson-ai-form" onSubmit={handleSubmit} style={{ width: "100%" }>
                    <M3DialogContent >
                        <TextField 
                            label="Argomento" 
                            value={argomento} 
                            onChange={e => setArgomento(e.target.value)} 
                            required 
                        />
                        
                        <div  style={{ display: "grid", gridTemplateColumns: "1fr 1fr" }>
                            <SelectField label="Classe" value={classe} onChange={e => setClasse(e.target.value)} required>
                                {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                            </SelectField>
                            <SelectField label="Materia" value={materia} onChange={e => setMateria(e.target.value)} required>
                                {disciplines.map(d => <option key={d} value={d}>{d}</option>)}
                            </SelectField>
                        </div>

                        <div>
                            <div  style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }>
                                <label  style={{color: "layers.sys.color.primary", textTransform: "uppercase"}>Obiettivi</label>
                                {matchingCurriculum && (
                                    <M3Button 
                                        type="button" 
                                        onClick={() => setIsObjectivePickerOpen(true)}
                                        variant="tonal"
                                         style={{ textTransform: "uppercase", letterSpacing: "0.1em", borderRadius: layers.ref.shape.corner.medium }
                                        title="Seleziona dal curricolo"
                                    >
                                        <span  style={{ fontSize: "0.875rem" }>library_add</span>
                                        Curricolo
                                    </M3Button>
                                )}
                            </div>
                            <TextArea
                                label="Elenco obiettivi didattici per la lezione..."
                                value={obiettivi}
                                onChange={e => setObiettivi(e.target.value)}
                                rows={5}
                                placeholder="Elenco obiettivi didattici per la lezione..."
                                containerClassName="shadow-inner !bg-[var(--md-sys-color-surfaceContainerLow)]est"
                            />
                            {matchingCurriculum && !obiettivi && (
                                <p  style={{fontSize: "0.75rem", color: "layers.sys.color.primary", marginTop: layers.ref.spacing['4'], display: "flex", alignItems: "center", gap: layers.ref.spacing['8'], fontWeight: "bold", cursor: "pointer"} onClick={() => setIsObjectivePickerOpen(true)}>
                                    <span  style={{ fontSize: "0.875rem" }>info</span> 
                                    Curricolo disponibile: {matchingCurriculum.gradeLevel} di {matchingCurriculum.subject}
                                </p>
                            )}
                        </div>
                        
                        {slots && availableSlots.length > 0 && (
                            <div style={{ marginTop: 'var(--md-sys-spacing-6)' }>
                                <label style={{ display: 'block', fontSize: 'var(--md-sys-typescale-body-large-size)', fontWeight: 'var(--md-sys-typescale-body-large-weight)', color: 'var(--md-sys-color-on-surface)', marginBottom: 'var(--md-sys-spacing-3)' }>
                                    Seleziona uno slot disponibile
                                </label>
                                <div  style={{ display: "flex", flexWrap: "wrap" }>
                                    {availableSlots.map(([key, slot]) => (
                                        <button
                                            key={key}
                                            type="button"
                                            onClick={() => setSelectedSlotKey(prev => prev === key ? '' : key)}
                                            className={`chip !h-12 !px-8 ${selectedSlotKey === key ? 'chip-selected border-primary' : 'bg-[var(--md-sys-color-surfaceContainerHigh)]'}`}
                                        >
                                            {selectedSlotKey === key && <span  style={{ fontSize: "1.25rem" }>check</span>}
