                                        }} 
                                        variant="text"
                                        
                                    >
                                        <span >close</span>
                                    </M3Button>
                                </div>
                            ))}
                            <M3Button 
                                onClick={() => {
                                    const newNuclei = [...selectedCurriculum.nuclei];
                                    newNuclei[nIdx].objectives.push({ id: `obj-${Date.now()}`, text: '', type: 'knowledge' });
