                    <div style={{display: "flex", flexDirection: "column", gap: "var(--md-sys-spacing-6)"}>
                        <div>
                            <SelectField
                                id="import-target-class"
                                label="Destinazione"
                                value={targetClass}
                                onChange={e => setTargetClass(e.target.value)}
                                required
