                                <div style={{ color: var(--md-sys-color-on)-tertiary-container ,  opacity: "0.9" } dangerouslySetInnerHTML={{ __html: infoMessage.replace(/\n/g, '<br />') }} />
                            </div>
                        )}
                    </div>
                );

            case 'mapping':
                return (
                    <div style={{display: "flex", flexDirection: "column", gap: "var(--md-sys-spacing-6)"}}>
                        <InfoCard
                            title="Mappa le colonne"
                            description={`File: ${fileName} | Destinazione: ${targetClass === 'AUTO' ? 'Rilevamento Automatico' : targetClass}`}
                            icon="auto_awesome"
                            variant="primary"
                            
                        />

                        <p style={{ color: "var(--md-sys-color-onSurfaceVariant)", paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)" }}>
                            Il sistema ha tentato di associare automaticamente le colonne. Verifica o correggi le associazioni.
