                        <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: "var(--md-sys-spacing-8)"}}>
                            <SelectField
                                id="map-cognome"
                                label="Colonna COGNOME"
                                value={columnMap.cognome}
                                onChange={e => setColumnMap(p => ({ ...p, cognome: e.target.value }))}
                            >
                                <option value="">Seleziona...</option>
                                {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                            </SelectField>
                            <SelectField
                                id="map-nome"
                                label="Colonna NOME"
                                value={columnMap.nome}
                                onChange={e => setColumnMap(p => ({ ...p, nome: e.target.value }))}
                            >
                                <option value="">Seleziona...</option>
                                {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                            </SelectField>
                            {targetClass === 'AUTO' && (
                                <div >
                                    <SelectField
                                        id="map-classe"
                                        label="Colonna CLASSE"
                                        value={columnMap.classe}
                                        onChange={e => setColumnMap(p => ({ ...p, classe: e.target.value }))}
                                    >
                                        <option value="">Seleziona...</option>
                                        {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                                    </SelectField>
                                </div>
                            )}
                        </div>

                        <div>
                            <h4  style={{textTransform: "uppercase", color: "var(--md-sys-color-primary)", fontWeight: "bold", marginBottom: "var(--md-sys-spacing-6)", paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}}>Anteprima Dati (Prime 3 righe)</h4>
                            <div style={{ borderRadius: "var(--md-sys-shape-corner-large)" , overflowX: "auto", border: "1px solid var(--md-sys-color-outline)"}>
                                <table style={{ width: "100%", fontSize: "0.875rem", textAlign: "left" }}>
                                    <thead style={{ color: "var(--md-sys-color-onSurfaceVariant)", backgroundColor: "var(--md-sys-color-surfaceContainerHigh)" ,  fontSize: "0.75rem", textTransform: "uppercase", fontWeight: "bold" }>
                                        <tr>
                                            {csvHeaders.map(h => <th key={h}  style={{paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)", whiteSpace: "nowrap"}}>{h}</th>)}
                                        </tr>
                                    </thead>
                                    <tbody >
                                        {csvData.slice(0, 3).map((row, index) => (
                                            <tr key={index}  style={{backgroundColor: "var(--md-sys-color-surface)", transition: "color 300ms"}}>
                                                {csvHeaders.map(h => <td key={h} style={{ color: "var(--md-sys-color-onPrimary)" , paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)", whiteSpace: "nowrap", fontWeight: "500"}>{row[h]}</td>)}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                );

            case 'confirm':
                return (
                    <div style={{display: "flex", flexDirection: "column", gap: "var(--md-sys-spacing-6)"}}>
                        <InfoCard
                            title="Conferma Importazione"
                            description={`Stai per importare ${studentsToImport.length} studenti. Gli studenti già presenti saranno ignorati.`}
                            icon="check_circle"
                            variant="secondary"
                            
                        />

                        {targetClass === 'AUTO' && (
                            <div style={{ backgroundColor: "var(--md-sys-color-surfaceContainerLow)", borderRadius: "var(--md-sys-shape-corner-large)" , padding: "var(--md-sys-spacing-8)", border: "1px solid var(--md-sys-color-outline)", fontSize: "0.875rem", display: "flex", gap: "var(--md-sys-spacing-6)", alignItems: "flex-start"}>
                                <span  style={{color: "var(--md-sys-color-primary)", fontSize: "1.25rem"}}>info</span>
                                <div>
                                    <p style={{ color: "var(--md-sys-color-onPrimary)" , fontWeight: "bold", marginBottom: "var(--md-sys-spacing-4)"}>Nota Importante</p>
                                    <p style={{ color: "var(--md-sys-color-onSurfaceVariant)" }}>Gli studenti verranno assegnati alle classi indicate nel file. Se una classe nel file non esiste nelle tue Impostazioni, lo studente verrà comunque importato ma la classe sarà creata implicitamente.</p>
                                </div>
                            </div>
                        )}

                        <div style={{ borderRadius: "var(--md-sys-shape-corner-large)" , overflowY: "auto", border: "1px solid var(--md-sys-color-outline)"}>
                            <table style={{ width: "100%", fontSize: "0.875rem", textAlign: "left" }}>
                                <thead style={{ color: "var(--md-sys-color-onSurfaceVariant)", backgroundColor: "var(--md-sys-color-surfaceContainerHigh)" ,  fontSize: "0.75rem", textTransform: "uppercase", fontWeight: "bold" }>
                                    <tr>
                                        <th  style={{paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}}>Cognome</th>
                                        <th  style={{paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}}>Nome</th>
                                        <th  style={{paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}}>Classe</th>
                                    </tr>
                                </thead>
                                <tbody >
                                    {studentsToImport.map((student, index) => (
                                        <tr key={index}  style={{backgroundColor: "var(--md-sys-color-surface)", transition: "color 300ms"}}>
                                            <td style={{ color: "var(--md-sys-color-onPrimary)" , paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)", fontWeight: "bold"}>{student.cognome}</td>
                                            <td style={{ color: "var(--md-sys-color-onPrimary)" , paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}>{student.nome}</td>
                                            <td  style={{paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)"}}><span style={{ color: var(--md-sys-color-on)-primaryContainer , paddingLeft: "var(--md-sys-spacing-4)", paddingRight: "var(--md-sys-spacing-4)", borderRadius: "var(--md-sys-spacing-4)", backgroundColor: "var(--md-sys-color-primaryContainer)", fontWeight: "900", fontSize: "0.75rem"}>{student.classe}</span></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                );
            default:
                return null;
        }
    };

    return (
        <M3Dialog
            onClose={onClose}
            title={step === 'upload' ? 'Importa Studenti' : step === 'mapping' ? 'Mappatura Colonne' : 'Conferma Importazione'}
            maxWidth="lg"
            level={1}
        >
            <M3DialogContent style={{ backgroundColor: "var(--md-sys-color-surfaceContainerHigh)"/30 }}>
                {renderContent()}
            </M3DialogContent>
            <M3DialogActions>
                {step === 'upload' && (
                    <M3Button onClick={onClose} variant="text">Annulla</M3Button>
                )}
                {step === 'mapping' && (
                    <>
                        <M3Button type="button" onClick={() => { setStep('upload'); setInfoMessage(''); setError(''); }} variant="text">Indietro</M3Button>
                        <M3Button type="button" onClick={() => setStep('confirm')} disabled={!columnMap.cognome || !columnMap.nome || (targetClass === 'AUTO' && !columnMap.classe)} variant="filled">Avanti</M3Button>
                    </>
                )}
                {step === 'confirm' && (
                    <>
                        <M3Button type="button" onClick={() => setStep('mapping')} variant="text">Indietro</M3Button>
                        <M3Button type="button" onClick={handleImport} variant="filled">Importa Studenti</M3Button>
                    </>
                )}
            </M3DialogActions>
        </M3Dialog>
    );
};

