                    </div>
                </div>
                <div >
                    <M3Button onClick={() => setIsInterviewModeOpen(true)} variant="tonal" >
                        <span >record_voice_over</span>
                        Colloquio
                    </M3Button>
                    <M3Button onClick={handleExportPdf} variant="filled"  disabled={isExporting}>
                        <span >download</span>
                        Esporta PDF
                    </M3Button>
