            </div>

            {isInterviewModeOpen && (
                <StudentInterviewModal 
                    student={student}
                    onClose={() => setIsInterviewModeOpen(false)}
                    onSave={() => {
                        // Logic to save interview note
                        setIsInterviewModeOpen(false);
                    }}
                />
            )}
        </div>
    );
};

