                                : 'translateY(-50%)',
                            transformOrigin: 'top left',
                            transition: 'all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1)',
                            color: isFocused
                                ? layers.sys.color.primary
                                : layers.sys.color.onSurfaceVariant,
                            pointerEvents: 'none',
                            zIndex: 1
                        }
                    >
                        {label}
                    </M3Typography>
                    <input
                        {...props}
                        value={value}
                        data-testid={dataTestId}
                        style={{
                            width: '100%',
                            border: 'none',
                            backgroundColor: 'transparent',
                            color: layers.sys.color.onSurface,
                            fontSize: 'var(--md-sys-typescale-body-large-font-size)',
                            fontFamily: 'var(--md-sys-typescale-body-large-font-family)',
                            fontWeight: 'var(--md-sys-typescale-body-large-font-weight)',
                            lineHeight: 'var(--md-sys-typescale-body-large-line-height)',
                            letterSpacing: 'var(--md-sys-typescale-body-large-letter-spacing)',
                            outline: 'none',
                            paddingTop: isLabelFloating ? layers.ref.spacing['2'] : 0,
                            transition: 'padding-top 0.2s cubic-bezier(0.4, 0.0, 0.2, 1)'
                        }
                        placeholder=""
                        aria-label={label}
                        aria-invalid={error ? 'true' : undefined}
                        aria-describedby={describedBy}
                        onFocus={(e) => {
                            setIsFocused(true);
                            props.onFocus?.(e);
                        }}
                        onBlur={(e) => {
                            setIsFocused(false);
                            props.onBlur?.(e);
                        }}
                    />
                </div>
                {error && (
                    <span
                        style={{
                            fontFamily: 'Material Symbols Outlined',
                            color: layers.sys.color.error,
                            fontSize: layers.ref.spacing['4']
                        }
                        aria-hidden="true"
                    >
                        error
                    </span>
                )}
            </div>
            {error && errorMessage && (
                <div
                    id={describedBy}
                    style={{display: 'flex',
                        alignItems: 'center',
                        gap: layers.ref.spacing['1'],
                        marginTop: layers.ref.spacing['1']}
                >
                    <span
                        style={{
                            fontFamily: 'Material Symbols Outlined',
                            color: layers.sys.color.error,
                            fontSize: 'var(--md-sys-typescale-body-small-font-size)'
                        }
                        aria-hidden="true"
                    >
                        error
                    </span>
                    <M3Typography
                        variant="body-small"
                        style={{color: layers.sys.color.error}
                    >
                        {errorMessage}
                    </M3Typography>
                </div>
            )}
        </div>
    );
};

export default TextField;

